import novamind_api as nm, json
ov = nm.market.get_market_overview()
kg = ov['known_groups']
print("type known_groups:", type(kg))
if isinstance(kg, list):
    for g in kg:
        gid = g.get('group_id') or g.get('id')
        if gid in ('S2','S1','S3','D_S06','D_S08'):
            print(json.dumps(g, indent=1)[:1200])
elif isinstance(kg, dict):
    for gid in ('S2','D_S06','D_S08'):
        if gid in kg: print(gid, json.dumps(kg[gid])[:1200])
print("\nmacro:", json.dumps(ov.get('macroeconomic'))[:300])
